/**
 * Single-pass extraction of tool usage stats (skills, MCP servers) and
 * tool profile (category counts) from parsed session JSONL.
 */
export function extractToolMetrics(sessionsMap: Record<string, string>): {
  skillsUsed: string[]
  mcpServersUsed: { name: string; count: number }[]
  toolProfile: ToolProfile | null
} {
  const skills = new Set<string>()
  const mcpCounts = new Map<string, number>()
  const counts = { shell: 0, fileOps: 0, search: 0, mcp: 0, agent: 0, other: 0 }
  let total = 0

  for (const jsonl of Object.values(sessionsMap)) {
    if (typeof jsonl !== "string") continue

    for (const line of jsonl.split("\n")) {
      if (!line.trim()) continue

      let parsed: Record<string, unknown>
      try {
        parsed = JSON.parse(line)
      } catch {
        continue
      }

      if (parsed.type !== "assistant") continue
      const message = parsed.message as Record<string, unknown> | undefined
      if (!message?.content || !Array.isArray(message.content)) continue

      for (const block of message.content as Array<Record<string, unknown>>) {
        if (block?.type !== "tool_use" || !block.name) continue
        const name = block.name as string
        total++

        // Tool profile categorization
        if (name === "Bash") {
          counts.shell++
        } else if (["Read", "Write", "Edit"].includes(name)) {
          counts.fileOps++
        } else if (["Grep", "Glob"].includes(name)) {
          counts.search++
        } else if (name.startsWith("mcp__")) {
          counts.mcp++
        } else if (name === "Agent" || name === "Skill") {
          counts.agent++
        } else {
          counts.other++
        }

        // Tool usage extraction (skills + MCP servers)
        if (name === "Skill") {
          const skill = (block.input as Record<string, unknown>)?.skill
          if (typeof skill === "string" && skill) {
            skills.add(skill)
          }
        } else if (name.startsWith("mcp__")) {
          const segments = name.split("__")
          if (segments.length >= 3 && segments[1]) {
            mcpCounts.set(segments[1], (mcpCounts.get(segments[1]) ?? 0) + 1)
          }
        }
      }
    }
  }

  let toolProfile: ToolProfile | null = null
  if (total > 0) {
    const keys = ["shell", "fileOps", "search", "mcp", "agent", "other"] as const
    const categories = Object.fromEntries(keys.map((k) => [k, { count: counts[k] }])) as Record<
      (typeof keys)[number],
      { count: number }
    >
    toolProfile = { categories, total }
  }

  return {
    skillsUsed: Array.from(skills),
    mcpServersUsed: Array.from(mcpCounts.entries())
      .map(([name, count]) => ({ name, count }))
      .sort((a, b) => b.count - a.count),
    toolProfile,
  }
}

