8	// AggregateRange collapses a slice of sessions into an ActivityRangeSummary.
9	// The [from, to] range is INCLUSIVE on both ends — a checkpoint whose
10	// timestamp equals from or to is counted. Sessions outside the range still
11	// contribute to session-level totals (Sessions, LinkedCommits, AgentCounts,
12	// ModelCounts); only their checkpoint-level tallies gate on the range.
13	func AggregateRange(sessions []ActivitySession, from, to time.Time) ActivityRangeSummary {
14		sum := ActivityRangeSummary{
15			From:            from,
16			To:              to,
17			LabelCounts:     map[string]int{},
18			FocusAreaCounts: map[string]int{},
19			AgentCounts:     map[string]int{},
20			ModelCounts:     map[string]int{},
21			ToolTimeMs:      map[string]int64{},
22		}
23		repos := map[string]bool{}
24		activeDays := map[string]bool{}
25		for _, s := range sessions {
26			sum.Sessions++
27			if s.Repo != "" {
28				repos[s.Repo] = true
29			}
30			sum.LinkedCommits += len(s.LinkedCommits)
31			for _, a := range s.AgentsUsed {
32				sum.AgentCounts[a]++
33			}
34			for _, m := range s.ModelsUsed {
35				sum.ModelCounts[m]++
36			}
37			for _, cp := range s.Checkpoints {
38				if cp.CreatedAt.Before(from) || cp.CreatedAt.After(to) {
39					continue
40				}
41				sum.Checkpoints++
42				if cp.IsTask {
43					sum.TaskCheckpoints++
44				}
45				activeDays[cp.CreatedAt.Format("2006-01-02")] = true
46				for _, lbl := range cp.Labels {
47					sum.LabelCounts[lbl]++
48				}
49				for _, fa := range cp.FocusAreas {
50					sum.FocusAreaCounts[fa]++
51				}
52			}
53		}
54		for r := range repos {
55			sum.ReposTouched = append(sum.ReposTouched, r)
56		}
57		sort.Strings(sum.ReposTouched)
58		sum.ActiveDays = len(activeDays)
59		return sum
60	}
