76	// DominantLabel returns the label whose share >= 0.55 AND leads the
77	// runner-up by >= 0.15. If no label qualifies, ok is false.
78	//
79	// Example:
80	//
81	//	counts = {feature_build: 6, bug_fix: 3, testing: 2} (total 11)
82	//	feature_build share 0.545 — below 0.55 threshold → ok=false
83	//
84	//	counts = {feature_build: 8, bug_fix: 2, testing: 1} (total 11)
85	//	feature_build share 0.727, lead 0.545 → ok=true, label="feature_build"
86	func DominantLabel(counts map[string]int) (string, bool) {
87		total := 0
88		for _, c := range counts {
89			total += c
90		}
91		if total == 0 {
92			return "", false
93		}
94		type kv struct {
95			k string
96			v int
97		}
98		all := make([]kv, 0, len(counts))
99		for k, v := range counts {
100			all = append(all, kv{k, v})
101		}
102		sort.SliceStable(all, func(i, j int) bool {
103			if all[i].v != all[j].v {
104				return all[i].v > all[j].v
105			}
106			return all[i].k < all[j].k
107		})
108		topShare := float64(all[0].v) / float64(total)
109		if topShare < 0.55 {
110			return "", false
111		}
112		if len(all) == 1 {
113			return all[0].k, true
114		}
115		runnerShare := float64(all[1].v) / float64(total)
116		if topShare-runnerShare < 0.15 {
117			return "", false
118		}
119		return all[0].k, true
120	}
