122	// AggregateByDay buckets checkpoints by day in the given tz, returning
123	// one ActivityDay per calendar day in the range (zero-activity days
124	// included).
125	func AggregateByDay(sessions []ActivitySession, from, to time.Time, tz *time.Location) []ActivityDay {
126		if tz == nil {
127			tz = time.UTC
128		}
129		startDay := dayStart(from, tz)
130		endDay := dayStart(to, tz)
131		days := int(endDay.Sub(startDay).Hours()/24) + 1
132		if days < 1 {
133			return nil
134		}
135		out := make([]ActivityDay, days)
136		byDay := map[string]*ActivityDay{}
137		for i := range days {
138			d := startDay.AddDate(0, 0, i)
139			out[i] = ActivityDay{
140				Date:            d,
141				LabelCounts:     map[string]int{},
142				FocusAreaCounts: map[string]int{},
143				ToolTimeMs:      map[string]int64{},
144			}
145			byDay[d.Format("2006-01-02")] = &out[i]
146		}
147		for _, s := range sessions {
148			for _, cp := range s.Checkpoints {
149				key := dayStart(cp.CreatedAt, tz).Format("2006-01-02")
150				d, ok := byDay[key]
151				if !ok {
152					continue
153				}
154				d.Checkpoints++
155				if cp.IsTask {
156					d.TaskCheckpoints++
157				}
158				if cp.LinkedCommit != "" {
159					d.LinkedCommits++
160				}
161				for _, lbl := range cp.Labels {
162					d.LabelCounts[lbl]++
163				}
164				for _, fa := range cp.FocusAreas {
165					d.FocusAreaCounts[fa]++
166				}
167			}
168		}
169		return out
170	}
